import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import Select from 'flarum/common/components/Select';
import { FREQUENCIES } from '../../common/models/SavedSearch';
import Link from 'flarum/common/components/Link';
import { filtersFor, maxSavedSearches, saveSearch, t, tText } from '../utils/savedSearches';

/**
 * Lista das buscas salvas na página de configurações: mudar a frequência
 * salva na hora; apagar pede confirmação.
 */
export default class SavedSearchesSettings extends Component {
  loading = true;
  searches = [];
  query = '';
  frequency = 'daily';
  adding = false;
  busy = {};
  oninit(vnode) {
    super.oninit(vnode);
    app.store.find('saved-searches').then(searches => {
      this.searches = searches;
    }).finally(() => {
      this.loading = false;
      m.redraw();
    });
  }
  view() {
    if (this.loading) return m(LoadingIndicator, {
      display: "block"
    });
    const max = maxSavedSearches();
    const full = this.searches.length >= max;
    return m("div", {
      className: "SavedSearchesSettings"
    }, m("p", {
      className: "helpText"
    }, t('settings.help')), this.searches.length === 0 ? m("p", {
      className: "SavedSearchesSettings-empty"
    }, t('settings.empty')) : m("ul", {
      className: "SavedSearchesSettings-list"
    }, this.searches.map(search => this.row(search))), full ? m("p", {
      className: "helpText"
    }, t('settings.limit_reached', {
      max
    })) : m("form", {
      className: "SavedSearchesSettings-add",
      onsubmit: this.add.bind(this)
    }, m("input", {
      className: "FormControl",
      "aria-label": tText('settings.query_label'),
      placeholder: tText('settings.query_placeholder'),
      maxlength: 255,
      value: this.query,
      oninput: e => this.query = e.target.value
    }), this.frequencySelect(this.frequency, value => this.frequency = value), m(Button, {
      type: "submit",
      className: "Button",
      loading: this.adding,
      disabled: !this.query.trim()
    }, t('settings.add_button'))));
  }
  row(search) {
    const id = search.id();
    return m("li", {
      className: "SavedSearchesSettings-item",
      key: id
    }, m(Link, {
      className: "SavedSearchesSettings-query",
      href: app.route('index', {
        q: search.query()
      })
    }, search.query()), this.frequencySelect(search.frequency(), value => this.changeFrequency(search, value), !!this.busy[id], search.query()), m(Button, {
      className: "Button Button--icon Button--link",
      icon: "fas fa-trash-alt",
      "aria-label": tText('settings.delete_button', {
        query: search.query()
      }),
      disabled: !!this.busy[id],
      onclick: () => this.remove(search)
    }));
  }
  frequencySelect(value, onchange, disabled, query) {
    if (disabled === void 0) {
      disabled = false;
    }
    const options = {};
    FREQUENCIES.forEach(frequency => options[frequency] = t(`frequencies.${frequency}`));
    return m(Select, {
      wrapperAttrs: {
        className: 'SavedSearchesSettings-frequency'
      },
      "aria-label": query ? tText('settings.frequency_of_label', {
        query
      }) : tText('settings.frequency_label'),
      options: options,
      value: value,
      disabled: disabled,
      onchange: onchange
    });
  }
  add(e) {
    e.preventDefault();
    if (!this.query.trim()) return;
    this.adding = true;
    saveSearch(this.query, filtersFor(this.query.trim()), this.frequency).then(search => {
      this.searches.push(search);
      this.query = '';
    }).catch(() => {}).finally(() => {
      this.adding = false;
      m.redraw();
    });
  }
  changeFrequency(search, frequency) {
    const id = search.id();
    const previous = search.frequency();
    this.busy[id] = true;

    // Em caso de erro o Model já devolve o atributo anterior; o select acompanha.
    search.save({
      frequency
    }).catch(() => search.pushAttributes({
      frequency: previous
    })).finally(() => {
      this.busy[id] = false;
      m.redraw();
    });
  }
  remove(search) {
    if (!confirm(tText('settings.delete_confirm', {
      query: search.query()
    }))) return;
    const id = search.id();
    this.busy[id] = true;
    search.delete().then(() => {
      this.searches = this.searches.filter(item => item !== search);
    }).catch(() => {}).finally(() => {
      this.busy[id] = false;
      m.redraw();
    });
  }
}
flarum.reg.add('ramon-saved-searches', 'forum/components/SavedSearchesSettings', SavedSearchesSettings);